/* ==========================================================================
   HANGING 3D ID CARD — a lanyard-style card on a physics rope.
   Vanilla Three.js, no extra physics library: the rope is a small
   verlet-integration chain, and the rigid card takes its rotation from
   the rope's tangent at the attachment point plus a damped "twist"
   oscillator (for the little 3D flip you get when you flick it).

   Customize:
   - CARD.name / CARD.role / CARD.tagline: text printed on the card face.
   - PHOTO_CANDIDATES: local image paths tried, in order, for the photo.
     If none load, a generated initials avatar is used automatically —
     so this works today even without a photo file present.
   - PX_WIDTH / PX_HEIGHT: on-screen size of the card, in CSS pixels.
   ========================================================================== */
(function () {
  console.log("[lanyard] script started");
  if (typeof THREE === "undefined") {
    console.warn("[lanyard] THREE is not defined — the three.js CDN script may be blocked or failed to load. The hanging card will not render.");
    return;
  }

  const container = document.getElementById("lanyard");
  const canvas = document.getElementById("lanyardCanvas");
  if (!container || !canvas) {
    console.warn("[lanyard] Could not find #lanyard / #lanyardCanvas in the page — the card markup may be missing from index.html. Stopping.", { container, canvas });
    return;
  }

  // Respect "reduce motion" by rendering a single static frame instead of animating.
  const REDUCE_MOTION = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const CARD = {
    name: "Anirban Maitra",
    role: "Data Scientist",
    tagline: "ACCESS: GRANTED",
  };
  /*const PHOTO_CANDIDATES = ["assets/profile.jpg", "assets/profile.jpeg", "assets/profile.png"];*/
  const PHOTO_CANDIDATES = [
    "data:image/jpeg;base64,"
  ]
  const PX_WIDTH = 180;
  const PX_HEIGHT = 250;

  /* ---------------------------------------------------------------------
     Renderer / scene / camera
     --------------------------------------------------------------------- */
  let width = container.clientWidth || 220;
  let height = container.clientHeight || 560;

  const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(width, height, false);
  console.log("[lanyard] renderer initialized:", { width, height, webgl2: renderer.capabilities.isWebGL2 });

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(30, width / height, 0.1, 100);
  camera.position.set(0, 0, 9);
  camera.lookAt(0, 0, 0);

  scene.add(new THREE.AmbientLight(0xffffff, 0.65));
  const key = new THREE.DirectionalLight(0xfff2d9, 0.9);
  key.position.set(2, 3, 4);
  scene.add(key);
  const rim = new THREE.PointLight(0xffb020, 0.8, 20);
  rim.position.set(-2, -1, 3);
  scene.add(rim);

  // world-units-per-pixel, derived from the actual camera/container so the
  // card renders at an exact CSS pixel size regardless of tuning.
  function worldScale() {
    const vh = 2 * Math.tan((camera.fov * Math.PI) / 360) * camera.position.z;
    return height / vh; // px per world unit
  }

  /* ---------------------------------------------------------------------
     Rope (verlet integration)
     --------------------------------------------------------------------- */
  const SEGMENTS = 10;
  let scale = worldScale();
  let worldH = height / scale;
  const anchor = new THREE.Vector2(0, worldH / 2 - 0.45);
  const ropeRestLen = worldH * 0.34;
  const segLen = ropeRestLen / (SEGMENTS - 1);

  let rope = [];
  function resetRope() {
    rope = [];
    for (let i = 0; i < SEGMENTS; i++) {
      const y = anchor.y - i * segLen;
      rope.push({ x: anchor.x, y: y, ox: anchor.x, oy: y });
    }
  }
  resetRope();

  const GRAVITY = -0.018;
  const DAMPING = 0.985;
  const CONSTRAINT_ITERATIONS = 6;

  let dragging = false;
  let dragTarget = new THREE.Vector2();
  let lastDragTarget = new THREE.Vector2();
  let dragVelocity = new THREE.Vector2();

  function stepRope(t) {
    const wind = Math.sin(t * 0.6) * 0.0009 + Math.sin(t * 1.7 + 1.3) * 0.0004;

    for (let i = 1; i < rope.length; i++) {
      const p = rope[i];
      if (dragging && i === rope.length - 1) {
        p.ox = p.x; p.oy = p.y;
        p.x = dragTarget.x; p.y = dragTarget.y;
        continue;
      }
      const vx = (p.x - p.ox) * DAMPING;
      const vy = (p.y - p.oy) * DAMPING;
      p.ox = p.x; p.oy = p.y;
      p.x += vx + wind;
      p.y += vy + GRAVITY;
    }

    for (let iter = 0; iter < CONSTRAINT_ITERATIONS; iter++) {
      rope[0].x = anchor.x; rope[0].y = anchor.y;
      for (let i = 0; i < rope.length - 1; i++) {
        const a = rope[i], b = rope[i + 1];
        const dx = b.x - a.x, dy = b.y - a.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 0.0001;
        const diff = (dist - segLen) / dist;
        const fixedA = i === 0;
        const fixedB = dragging && i + 1 === rope.length - 1;
        if (fixedA && fixedB) continue;
        let moveA = 0.5, moveB = 0.5;
        if (fixedA) { moveA = 0; moveB = 1; }
        if (fixedB) { moveA = 1; moveB = 0; }
        a.x += dx * diff * moveA; a.y += dy * diff * moveA;
        b.x -= dx * diff * moveB; b.y -= dy * diff * moveB;
      }
    }
  }

  /* ---------------------------------------------------------------------
     Rope mesh (thin tube through the verlet points)
     --------------------------------------------------------------------- */
  const ropeMaterial = new THREE.MeshStandardMaterial({ color: 0x3a4644, roughness: 0.6, metalness: 0.2 });
  let ropeMesh = null;
  function updateRopeMesh() {
    const pts = rope.map((p) => new THREE.Vector3(p.x, p.y, 0.80));
    const curve = new THREE.CatmullRomCurve3(pts);
    const geo = new THREE.TubeGeometry(curve, 24, 0.028, 6, false);
    if (ropeMesh) { scene.remove(ropeMesh); ropeMesh.geometry.dispose(); }
    ropeMesh = new THREE.Mesh(geo, ropeMaterial);
    scene.add(ropeMesh);
  }

  // static mount bracket at the very top, suggesting the rope is clipped
  // to the top edge of the browser
  const mountGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.50, 10);
  const mountMat = new THREE.MeshStandardMaterial({ color: 0xffb020, roughness: 0.4, metalness: 0.5 });
  const mount = new THREE.Mesh(mountGeo, mountMat);
  mount.position.set(anchor.x, worldH / 2 + 0.02, 0);
  scene.add(mount);

  const clipGeo = new THREE.TorusGeometry(0.09, 0.022, 8, 20);
  const clip = new THREE.Mesh(clipGeo, mountMat);
  scene.add(clip);

  /* ---------------------------------------------------------------------
     Card face texture (photo or generated initials avatar + text)
     --------------------------------------------------------------------- */
  const TEX_W = 512, TEX_H = Math.round((512 * PX_HEIGHT) / PX_WIDTH);
  const texCanvas = document.createElement("canvas");
  texCanvas.width = TEX_W; texCanvas.height = TEX_H;
  const ctx = texCanvas.getContext("2d");
  const cardTexture = new THREE.CanvasTexture(texCanvas);
  cardTexture.colorSpace = THREE.SRGBColorSpace || cardTexture.colorSpace;
  // The canvas isn't power-of-two on both axes (512 x ~712). Under WebGL1,
  // that combined with default mipmap filtering can silently render as a
  // solid black texture. Disable mipmaps and use plain linear filtering so
  // it displays correctly on every device.
  cardTexture.generateMipmaps = false;
  cardTexture.minFilter = THREE.LinearFilter;
  cardTexture.magFilter = THREE.LinearFilter;
  if ("colorSpace" in cardTexture && THREE.SRGBColorSpace) {
    cardTexture.colorSpace = THREE.SRGBColorSpace;
  }

  function roundRectPath(c, x, y, w, h, r) {
    c.beginPath();
    c.moveTo(x + r, y);
    c.arcTo(x + w, y, x + w, y + h, r);
    c.arcTo(x + w, y + h, x, y + h, r);
    c.arcTo(x, y + h, x, y, r);
    c.arcTo(x, y, x + w, y, r);
    c.closePath();
  }

  function drawInitials(cx, cy, r, initials) {
    const grad = ctx.createLinearGradient(cx - r, cy - r, cx + r, cy + r);
    grad.addColorStop(0, "#FFB020");
    grad.addColorStop(1, "#5FD4C4");
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.fillStyle = "rgba(11,15,16,0.88)";
    ctx.font = `600 ${Math.round(r * 0.72)}px 'IBM Plex Mono', monospace`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(initials, cx, cy + r * 0.05);
    ctx.restore();
  }

  function drawCardChrome(photoImg) {
    ctx.clearRect(0, 0, TEX_W, TEX_H);
    roundRectPath(ctx, 0, 0, TEX_W, TEX_H, 26);
    ctx.fillStyle = "#151C1F";
    ctx.fill();
    ctx.strokeStyle = "rgba(255,176,32,0.55)";
    ctx.lineWidth = 3;
    ctx.stroke();

    // header strip
    ctx.fillStyle = "rgba(255,176,32,0.08)";
    roundRectPath(ctx, 0, 0, TEX_W, 46, 26);
    ctx.fill();
    ctx.fillStyle = "#FFB020";
    ctx.font = "600 20px 'IBM Plex Mono', monospace";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("OWNER", TEX_W / 2, 25);

    // photo circle
    const cx = TEX_W / 2, cy = TEX_H * 0.38, r = TEX_W * 0.42;
    if (photoImg) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, Math.PI * 2);
      ctx.closePath();
      ctx.clip();
      const s = Math.max((r * 2) / photoImg.width, (r * 2) / photoImg.height);
      const iw = photoImg.width * s, ih = photoImg.height * s;
      ctx.drawImage(photoImg, cx - iw / 2, cy - ih / 2, iw, ih);
      ctx.restore();
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, Math.PI * 2);
      ctx.strokeStyle = "#FFB020";
      ctx.lineWidth = 4;
      ctx.stroke();
    } else {
      const initials = CARD.name.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase();
      drawInitials(cx, cy, r, initials);
    }

    // name / role
    ctx.fillStyle = "#E7ECE9";
    ctx.font = "600 26px 'IBM Plex Mono', monospace";
    ctx.textAlign = "center";
    ctx.fillText(CARD.name, TEX_W / 2, TEX_H * 0.75);

    ctx.fillStyle = "#8FA39C";
    ctx.font = "400 17px 'IBM Plex Sans', sans-serif";
    wrapText(CARD.role, TEX_W / 2, TEX_H * 0.80, TEX_W * 0.82, 20);

    // barcode-ish footer for flavor
    ctx.fillStyle = "#5FD4C4";
    ctx.font = "500 15px 'IBM Plex Mono', monospace";
    ctx.fillText(CARD.tagline, TEX_W / 2, TEX_H * 0.90);
    let bx = TEX_W * 0.18;
    const by = TEX_H * 0.945, bh = 16;
    ctx.fillStyle = "rgba(231,236,233,0.5)";
    while (bx < TEX_W * 0.82) {
      const bw = 2 + Math.random() * 5;
      ctx.fillRect(bx, by, bw, bh);
      bx += bw + 3 + Math.random() * 4;
    }

    cardTexture.needsUpdate = true;
  }

  function wrapText(text, x, y, maxWidth, lineHeight) {
    const words = text.split(" ");
    let line = "", lines = [];
    for (const w of words) {
      const test = line ? line + " " + w : w;
      if (ctx.measureText(test).width > maxWidth && line) { lines.push(line); line = w; }
      else line = test;
    }
    lines.push(line);
    const startY = y - ((lines.length - 1) * lineHeight) / 2;
    ctx.textAlign = "center";
    lines.forEach((l, i) => ctx.fillText(l, x, startY + i * lineHeight));
  }

  drawCardChrome(null); // draw a placeholder immediately, upgrade if a photo loads
  console.log("[lanyard] placeholder card face drawn:", TEX_W + "x" + TEX_H, "canvas has content:", texCanvas.toDataURL().length > 100);
  (function tryLoadPhoto(i) {
    if (i >= PHOTO_CANDIDATES.length) { console.log("[lanyard] no photo found at any of:", PHOTO_CANDIDATES, "— using initials avatar."); return; }
    const img = new Image();
    img.onload = () => {
      if (!img.naturalWidth || !img.naturalHeight) { tryLoadPhoto(i + 1); return; }
      console.log("[lanyard] photo loaded:", PHOTO_CANDIDATES[i], img.naturalWidth + "x" + img.naturalHeight);
      if (location.protocol === "file:") {
        console.warn(
          "[lanyard] Loaded " + PHOTO_CANDIDATES[i] + " over the file:// protocol. " +
          "Most browsers block canvas-based WebGL textures from local files opened this way " +
          "(the card will render blank instead of erroring loudly). " +
          "Serve this folder over http:// instead — e.g. run `python3 -m http.server` " +
          "in the project folder and open http://localhost:8000 — and the photo will appear normally."
        );
      }
      drawCardChrome(img);
    };
    img.onerror = () => { console.log("[lanyard] failed to load", PHOTO_CANDIDATES[i], "— trying next candidate."); tryLoadPhoto(i + 1); };
    img.src = PHOTO_CANDIDATES[i];
  })(0);

  // back-of-card texture (simple repeated wordmark, shown when the card twists)
  const backCanvas = document.createElement("canvas");
  backCanvas.width = TEX_W; backCanvas.height = TEX_H;
  const bctx = backCanvas.getContext("2d");
  roundRectPath(bctx, 0, 0, TEX_W, TEX_H, 26);
  bctx.fillStyle = "#12181A";
  bctx.fill();
  bctx.strokeStyle = "rgba(95,212,196,0.4)";
  bctx.lineWidth = 3;
  bctx.stroke();
  bctx.fillStyle = "rgba(143,163,156,0.35)";
  bctx.font = "600 15px 'IBM Plex Mono', monospace";
  bctx.textAlign = "center";
  for (let row = 0; row < 9; row++) {
    bctx.save();
    bctx.translate(TEX_W / 2, 30 + row * 46);
    bctx.rotate(-0.35);
    bctx.fillText("anirban.dev  ·  anirban.dev  ·  anirban.dev", 0, 0);
    bctx.restore();
  }
  const backTexture = new THREE.CanvasTexture(backCanvas);
  backTexture.generateMipmaps = false;
  backTexture.minFilter = THREE.LinearFilter;
  backTexture.magFilter = THREE.LinearFilter;

  /* ---------------------------------------------------------------------
     Card mesh
     --------------------------------------------------------------------- */
  scale = worldScale();
  const cardW = PX_WIDTH / scale;
  const cardH = PX_HEIGHT / scale;
  const cardDepth = 0.05;

  function roundedRectShape(w, h, r) {
    const shape = new THREE.Shape();
    const x = -w / 2, y = -h / 2;
    shape.moveTo(x + r, y);
    shape.lineTo(x + w - r, y);
    shape.quadraticCurveTo(x + w, y, x + w, y + r);
    shape.lineTo(x + w, y + h - r);
    shape.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    shape.lineTo(x + r, y + h);
    shape.quadraticCurveTo(x, y + h, x, y + h - r);
    shape.lineTo(x, y + r);
    shape.quadraticCurveTo(x, y, x + r, y);
    return shape;
  }

  const cardGroup = new THREE.Group();

  // amber border layer, slightly larger, sits behind the body
  const borderGeo = new THREE.ExtrudeGeometry(roundedRectShape(cardW + 0.045, cardH + 0.045, 0.16), { depth: cardDepth * 0.7, bevelEnabled: false });
  const borderMesh = new THREE.Mesh(borderGeo, new THREE.MeshStandardMaterial({ color: 0xffb020, roughness: 0.5, metalness: 0.3 }));
  borderMesh.position.z = -cardDepth * 0.55;
  cardGroup.add(borderMesh);

  // body
  const bodyGeo = new THREE.ExtrudeGeometry(roundedRectShape(cardW, cardH, 0.14), { depth: cardDepth, bevelEnabled: true, bevelThickness: 0.008, bevelSize: 0.008, bevelSegments: 2 });
  const bodyMesh = new THREE.Mesh(bodyGeo, new THREE.MeshStandardMaterial({ color: 0x151c1f, roughness: 0.55, metalness: 0.15 }));
  bodyMesh.position.z = -cardDepth / 2;
  cardGroup.add(bodyMesh);

  /*// printed face (photo/name/role)
  const frontGeo = new THREE.PlaneGeometry(cardW * 0.94, cardH * 0.94);
  const frontMesh = new THREE.Mesh(frontGeo, new THREE.MeshBasicMaterial({ map: cardTexture }));
  frontMesh.position.z = cardDepth / 2 + 0.002;
  cardGroup.add(frontMesh);*/

  // --- CORRECTED PRINTED FACE: use the generated card texture ---
  // The previous version used a solid red material here, which covered
  // the CanvasTexture containing the profile photo and card details.
  const frontGeo = new THREE.PlaneGeometry(cardW * 0.94, cardH * 0.94);
  const frontMat = new THREE.MeshBasicMaterial({
    map: cardTexture,
    side: THREE.DoubleSide,
    transparent: false,
    depthTest: true,
    depthWrite: true,
    polygonOffset: true,
    polygonOffsetFactor: -1,
    polygonOffsetUnits: -4
  });
  const frontMesh = new THREE.Mesh(frontGeo, frontMat);

  // IMPORTANT: the ExtrudeGeometry body occupies the full card depth.
  // Put the printed face clearly in front of the body's front surface.
  // The old +0.002 offset was too small and could be depth-occluded by
  // the solid card body, leaving the card looking completely empty.
  frontMesh.position.z = cardDepth / 2 + 0.025;
  frontMesh.renderOrder = 10;
  cardGroup.add(frontMesh);
  // ---------------------------------------------------------------

  // back face
  const backMesh = new THREE.Mesh(frontGeo.clone(), new THREE.MeshBasicMaterial({ map: backTexture }));
  backMesh.position.z = -cardDepth - 0.002;
  backMesh.rotation.y = Math.PI;
  cardGroup.add(backMesh);

  scene.add(cardGroup);

  // hit-test target — a slightly generous invisible plane for easy grabbing
  const hitGeo = new THREE.PlaneGeometry(cardW * 1.1, cardH * 1.1);
  const hitMesh = new THREE.Mesh(hitGeo, new THREE.MeshBasicMaterial({ visible: false }));
  cardGroup.add(hitMesh);

  /* ---------------------------------------------------------------------
     Twist oscillator (the little 3D flip on release/flick)
     --------------------------------------------------------------------- */
  let twist = 0, twistVel = 0;
  const TWIST_SPRING = 3.2, TWIST_DAMP = 3.4;

  /* ---------------------------------------------------------------------
     Interaction — drag to swing/flick
     --------------------------------------------------------------------- */
  const raycaster = new THREE.Raycaster();
  const ndc = new THREE.Vector2();
  const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
  const planeHit = new THREE.Vector3();

  function setNdcFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    ndc.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    ndc.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  }

  function worldPointFromEvent(e) {
    setNdcFromEvent(e);
    raycaster.setFromCamera(ndc, camera);
    raycaster.ray.intersectPlane(dragPlane, planeHit);
    return planeHit;
  }

  canvas.addEventListener("pointerdown", (e) => {
    setNdcFromEvent(e);
    raycaster.setFromCamera(ndc, camera);
    const hit = raycaster.intersectObject(hitMesh, false);
    if (hit.length === 0) return;
    dragging = true;
    canvas.classList.add("is-dragging");
    canvas.setPointerCapture(e.pointerId);
    const p = worldPointFromEvent(e);
    dragTarget.set(p.x, p.y);
    lastDragTarget.copy(dragTarget);
  });

  canvas.addEventListener("pointermove", (e) => {
    // hover cursor feedback even when not dragging
    if (!dragging) {
      setNdcFromEvent(e);
      raycaster.setFromCamera(ndc, camera);
      const hit = raycaster.intersectObject(hitMesh, false);
      canvas.style.cursor = hit.length ? "grab" : "default";
      return;
    }
    const p = worldPointFromEvent(e);
    lastDragTarget.copy(dragTarget);
    dragTarget.set(p.x, p.y);
    dragVelocity.set(dragTarget.x - lastDragTarget.x, dragTarget.y - lastDragTarget.y);
  });

  function endDrag(e) {
    if (!dragging) return;
    dragging = false;
    canvas.classList.remove("is-dragging");
    twistVel += dragVelocity.x * 22;
    dragVelocity.set(0, 0);
  }
  canvas.addEventListener("pointerup", endDrag);
  canvas.addEventListener("pointercancel", endDrag);
  canvas.addEventListener("pointerleave", (e) => { if (!dragging) canvas.style.cursor = "default"; });

  /* ---------------------------------------------------------------------
     Animation loop
     --------------------------------------------------------------------- */
  let t = 0;
  function animate() {
    t += 0.016;
    stepRope(t);
    updateRopeMesh();

    const tip = rope[rope.length - 1];
    const prev = rope[rope.length - 2];
    clip.position.set(tip.x, tip.y, 0);

    const dx = tip.x - prev.x, dy = tip.y - prev.y;
    const swingAngle = Math.atan2(dx, -dy); // 0 when hanging straight down

    twistVel += (-twist * TWIST_SPRING - twistVel * TWIST_DAMP) * 0.016;
    twist += twistVel * 0.016;

    const localDown = new THREE.Vector2(Math.sin(swingAngle), -Math.cos(swingAngle));
    cardGroup.position.set(
      tip.x + localDown.x * (cardH / 2 + 0.06),
      tip.y + localDown.y * (cardH / 2 + 0.06),
      0
    );
    cardGroup.rotation.z = swingAngle;
    cardGroup.rotation.y = twist;

    try {
      renderer.render(scene, camera);
    } catch (err) {
      console.error(
        "[lanyard] WebGL render failed — this is almost always the file:// canvas-taint " +
        "issue described above. Serve the site over http:// (e.g. `python3 -m http.server`) " +
        "and reload. Stopping the animation loop.", err
      );
      return; // stop requesting frames so the console isn't flooded
    }
    if (!REDUCE_MOTION) requestAnimationFrame(animate);
  }

  /* ---------------------------------------------------------------------
     Resize
     --------------------------------------------------------------------- */
  let resizeTimer;
  window.addEventListener("resize", () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      width = container.clientWidth || width;
      height = container.clientHeight || height;
      if (!width || !height) return;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height, false);
      scale = worldScale();
      worldH = height / scale;
      anchor.set(0, worldH / 2 - 0.45);
      mount.position.set(anchor.x, worldH / 2 + 0.02, 0);
      resetRope();
    }, 150);
  });

  const cs = getComputedStyle(container);
  console.log("[lanyard] container visibility check:", {
    display: cs.display,
    rect: container.getBoundingClientRect(),
    viewportWidth: window.innerWidth,
    note: cs.display === "none"
      ? "Container is hidden by the responsive breakpoint (viewport narrower than 1120px, or DevTools is eating page width). The card is working correctly but not shown at this size."
      : "Container is visible — if you still don't see the card, it's a genuine rendering issue, not a visibility/breakpoint one.",
  });

  try {
    animate(); // runs once and stops itself if prefers-reduced-motion is set
  } catch (err) {
    console.error("[lanyard] animate() threw an error — WebGL is likely unavailable in this browser:", err);
    container.style.display = "none";
  }
})();



























